N_PERM=1999
def safe(a,b,method):
 z=pd.DataFrame({'a':a,'b':b}).dropna();return (pearsonr(z.a,z.b).statistic if method=='Pearson' else spearmanr(z.a,z.b).statistic) if len(z)>3 and z.a.nunique()>1 and z.b.nunique()>1 else np.nan
def moran(x,xy,k=5,nperm=999):
 x=np.asarray(x,float);z=x-x.mean();nn=NearestNeighbors(n_neighbors=k+1).fit(xy).kneighbors(return_distance=False)[:,1:];W=np.zeros((len(x),len(x)));W[np.arange(len(x))[:,None],nn]=1;W=np.maximum(W,W.T);I=len(x)/W.sum()*(W*np.outer(z,z)).sum()/(z@z);rng=np.random.default_rng(SEED);pp=[]
 for _ in range(nperm):q=rng.permutation(z);pp.append(len(x)/W.sum()*(W*np.outer(q,q)).sum()/(q@q))
 return I,(np.sum(np.abs(pp)>=abs(I))+1)/(nperm+1),W.sum()/len(x)
def main():
 ids,X,y=load_xy();ids=ids.reset_index(drop=True);y=y.reset_index(drop=True);champ=pd.read_parquet(ROOT/'outputs/modeling/residual_signal_audit/stage6_architecture_optimization/predictions/oof_predictions.parquet');champ=champ[champ.architecture.eq('A_CURRENT_CH_H_T')][[ID,'repeat','fold','y_true','y_pred']].copy();champ['residual']=champ.y_true-champ.y_pred;champ['absolute_error']=abs(champ.residual);champ['squared_error']=champ.residual**2;assert champ.groupby(ID).size().eq(10).all() and not champ.duplicated([ID,'repeat']).any();champ.to_csv(T/'01_champion_oof_by_parcel_repetition.csv',index=False)
 m=champ.groupby(ID).agg(y_true=('y_true','first'),prediction_mean=('y_pred','mean'),prediction_median=('y_pred','median'),prediction_sd=('y_pred','std'),prediction_range=('y_pred',lambda x:x.max()-x.min()),residual_mean=('residual','mean'),residual_sd=('residual','std'),mean_absolute_error=('absolute_error','mean'),rmse_across_repetitions=('squared_error',lambda x:np.sqrt(x.mean())),mean_squared_error=('squared_error','mean'),overestimation_frequency=('residual',lambda x:(x<0).mean()),underestimation_frequency=('residual',lambda x:(x>0).mean()),error_gt_0_5_frequency=('absolute_error',lambda x:(x>.5).mean()),error_gt_1_0_frequency=('absolute_error',lambda x:(x>1).mean())).reset_index();m['mean_residual_squared']=m.residual_mean**2;m['sign_consistency']=m[['overestimation_frequency','underestimation_frequency']].max(axis=1);m['signed_error_pattern']=np.where(m.underestimation_frequency>=.8,'recurrent_underestimate',np.where(m.overestimation_frequency>=.8,'recurrent_overestimate','sign_variable'));m['aggregated_SSE_fraction']=m.mean_residual_squared/m.mean_residual_squared.sum();m['repetition_MSE_fraction']=m.mean_squared_error/m.mean_squared_error.sum()
 support=pd.read_csv(ROOT/'outputs/modeling/family_1/support_analysis/support/difficult_parcel_support.csv')[[ID,'difficult_all_3','y_outlier_given_similar_X','support_class']];m=m.merge(support,on=ID,how='left');m['difficult']=m.difficult_all_3.fillna(False);m['y_atypical']=m.y_outlier_given_similar_X.fillna(False);q1,q3=m.y_true.quantile([.25,.75]);m['yield_segment']=np.select([m.y_true<=q1,m.y_true>=q3],['LOW','HIGH'],'MID');n10=int(np.ceil(len(m)*.1));top=set(m.nlargest(n10,'mean_residual_squared')[ID]);m['top10_SSE']=m[ID].isin(top);m.to_csv(T/'02_parcel_error_master.csv',index=False)
 # Frozen A1/E3 coordinates and E3/A2 memberships.
 a1=pd.read_parquet(ROOT/'outputs/modeling/family_3/f3_1_1_structural_representation/tables/04_structural_coordinates.parquet');a1=a1[(a1.CONJUNTO=='TRAIN')&a1.representation_id.isin(['A1_COMPACT_PCA3','A2_FULL_BALANCED_PCA3'])];e3=pd.read_parquet(ROOT/'outputs/modeling/family_3/f3_1_2_structural_source_expansion/tables/09_e1_e3_coordinates.parquet');e3=e3[(e3.CONJUNTO=='TRAIN')&e3.representation_id.eq('E3_AUGMENTED_PCA3')];A=a1[a1.representation_id.eq('A1_COMPACT_PCA3')][[ID,'F1','F2','F3']].rename(columns={f'F{i}':f'A1_PC{i}' for i in range(1,4)});E=e3[[ID,'F1','F2','F3']].rename(columns={f'F{i}':f'E3_PC{i}' for i in range(1,4)});m=m.merge(A,on=ID).merge(E,on=ID)
 Z=m[[f'E3_PC{i}' for i in range(1,4)]].to_numpy();gm=GaussianMixture(2,covariance_type='diag',reg_covar=1e-5,n_init=50,random_state=SEED).fit(Z);P=gm.predict_proba(Z);m['E3_prob_1']=P[:,0];m['E3_prob_2']=P[:,1];m['E3_max_probability']=P.max(1);m['E3_entropy']=-(P*np.log(P+1e-12)).sum(1)/np.log(2);m['E3_gmm_distance']=np.min(np.sqrt(((Z[:,None,:]-gm.means_[None,:,:])**2/gm.covariances_[None,:,:]).sum(2)),axis=1);m['A1_distance']=np.sqrt((StandardScaler().fit_transform(m[[f'A1_PC{i}' for i in range(1,4)]] )**2).sum(1));m['E3_distance']=np.sqrt((StandardScaler().fit_transform(m[[f'E3_PC{i}' for i in range(1,4)]])**2).sum(1));old=pd.read_parquet(ROOT/'outputs/modeling/family_3/f3_1_1_structural_representation/tables/08_gmm_membership_probabilities.parquet');old=old[(old.CONJUNTO=='TRAIN')&old.gmm_id.eq('A2_FULL_BALANCED_PCA3_GMM2_diag')][[ID,'prob_component_1','prob_component_2']].rename(columns={'prob_component_1':'A2_prob_1','prob_component_2':'A2_prob_2'});m=m.merge(old,on=ID);m.to_csv(T/'02_parcel_error_master.csv',index=False)
 # Categories and overlap.
 cats=['yield_segment','difficult','y_atypical','top10_SSE','signed_error_pattern'];m[[ID,'y_true']+cats].to_csv(T/'03_extreme_categories.csv',index=False);sets={'LOW':set(m.loc[m.yield_segment=='LOW',ID]),'HIGH':set(m.loc[m.yield_segment=='HIGH',ID]),'difficult':set(m.loc[m.difficult,ID]),'y_atypical':set(m.loc[m.y_atypical,ID]),'top10_SSE':set(m.loc[m.top10_SSE,ID]),'underestimate':set(m.loc[m.signed_error_pattern=='recurrent_underestimate',ID]),'overestimate':set(m.loc[m.signed_error_pattern=='recurrent_overestimate',ID])};ov=[]
 for a,sa in sets.items():
  for b,sb in sets.items():ov.append({'set_a':a,'set_b':b,'n_a':len(sa),'n_b':len(sb),'intersection':len(sa&sb),'jaccard':len(sa&sb)/len(sa|sb) if sa|sb else np.nan})
 pd.DataFrame(ov).to_csv(T/'04_category_overlap.csv',index=False)
 # Yield memberships with one predeclared permutation statistic: range of mean p1 across LOW/MID/HIGH.
 gy=[]
 for scheme,probcols in [('E3',['E3_prob_1','E3_prob_2']),('A2',['A2_prob_1','A2_prob_2'])]:
  for seg,g in m.groupby('yield_segment'):
   for k,c in enumerate(probcols,1):base=m[c].mean();w=g[c].sum();gy.append({'membership':scheme,'yield_segment':seg,'component':k,'n_parcels':len(g),'effective_weight':w,'P_component_given_segment':w/len(g),'P_segment_given_component':w/m[c].sum(),'component_reference':base,'enrichment_ratio':(w/len(g))/base})
 rng=np.random.default_rng(SEED);obs=m.groupby('yield_segment').E3_prob_1.mean().pipe(lambda x:x.max()-x.min());perm=[]
 for _ in range(N_PERM):perm.append(pd.DataFrame({'seg':m.yield_segment,'p':rng.permutation(m.E3_prob_1)}).groupby('seg').p.mean().pipe(lambda x:x.max()-x.min()))
 gyf=pd.DataFrame(gy);gyf['permutation_statistic_E3_p1_range']=obs;gyf['permutation_p_value']=(np.sum(np.array(perm)>=obs)+1)/(N_PERM+1);gyf.to_csv(T/'05_gmm_yield_associations.csv',index=False)
 # Membership-weighted error.
 ge=[]
 for scheme,cols in [('E3',['E3_prob_1','E3_prob_2']),('A2',['A2_prob_1','A2_prob_2'])]:
  for k,c in enumerate(cols,1):
   w=m[c];den=w.sum();ge.append({'membership':scheme,'component':k,'effective_n':den,'weighted_residual':(w*m.residual_mean).sum()/den,'weighted_absolute_error':(w*m.mean_absolute_error).sum()/den,'weighted_squared_error':(w*m.mean_residual_squared).sum()/den,'SSE_fraction':(w*m.mean_residual_squared).sum()/(m.mean_residual_squared.sum()),'weighted_prediction_sd':(w*m.prediction_sd).sum()/den,'difficult_weighted_rate':(w*m.difficult).sum()/den,'yatypical_weighted_rate':(w*m.y_atypical).sum()/den,'extreme_error_weighted_rate':(w*m.top10_SSE).sum()/den})
 pd.DataFrame(ge).to_csv(T/'06_gmm_error_associations.csv',index=False)
 # Factor/error associations, fixed targets, with top-two influence sensitivity.
 vars=[f'A1_PC{i}' for i in range(1,4)]+[f'E3_PC{i}' for i in range(1,4)]+['A1_distance','E3_distance','E3_gmm_distance','E3_entropy','E3_max_probability'];targets=['y_true','prediction_mean','residual_mean','mean_absolute_error','mean_residual_squared','prediction_sd','sign_consistency'];fa=[];keep=~m.top10_SSE
 for v in vars:
  for z in targets:
   for method in ['Pearson','Spearman']:fa.append({'structural_variable':v,'outcome':z,'method':method,'correlation':safe(m[v],m[z],method),'correlation_excluding_top10_SSE':safe(m.loc[keep,v],m.loc[keep,z],method)})
 pd.DataFrame(fa).to_csv(T/'07_factor_error_associations.csv',index=False)
 # Error stability classification.
 stab=m[[ID,'residual_mean','residual_sd','mean_absolute_error','rmse_across_repetitions','prediction_sd','sign_consistency','signed_error_pattern','aggregated_SSE_fraction','repetition_MSE_fraction','difficult','y_atypical','top10_SSE']].copy();stab['diagnostic_type']=np.select([(stab.sign_consistency>=.8)&(stab.mean_absolute_error>=m.mean_absolute_error.quantile(.75)),stab.prediction_sd>=m.prediction_sd.quantile(.75),stab.mean_absolute_error>=m.mean_absolute_error.quantile(.75)],['recurrent_bias_large_error','fit_instability','consistently_large_magnitude'],default='ordinary');stab.to_csv(T/'08_error_stability.csv',index=False);m.sort_values('mean_residual_squared',ascending=False)[[ID,'y_true','residual_mean','mean_residual_squared','aggregated_SSE_fraction','repetition_MSE_fraction','yield_segment','difficult','y_atypical','top10_SSE','signed_error_pattern','E3_prob_1','E3_entropy','E3_distance']].to_csv(T/'09_sse_concentration.csv',index=False)
 # Spatial diagnostics and maps.
 import geopandas as gpd
 geo=gpd.read_file(ROOT/'data/original/02_conjunto_70_30/Parcelas_Reto_AGC_CONJUNTO.shp').to_crs(6372);geo[ID]=geo.ID_POLIGON.astype(str);g=geo.merge(m,on=ID);xy=np.c_[g.geometry.centroid.x,g.geometry.centroid.y];sp=[]
 for v in ['residual_mean','mean_absolute_error']:
  I,pv,neigh=moran(g[v],xy);sp.append({'variable':v,'Moran_I':I,'permutation_p':pv,'neighbors_definition':'symmetric 5-nearest centroids','mean_neighbors':neigh})
 pd.DataFrame(sp).to_csv(T/'10_spatial_diagnostics.csv',index=False)
 # Target-free risk candidates, no model trained.
 clim=X.copy();clim[ID]=ids;mods=['CLIMATE_precip_early_sum','CLIMATE_tmin_mean_slope','CLIMATE_tmax_mean_peak_day','CLIMATE_dtr_mean_std'];pre=m.merge(clim[[ID]+mods],on=ID);risk=[]
 for v in vars+mods:
  risk.append({'candidate_signal':v,'available_pre_yield':True,'spearman_abs_error':safe(pre[v],pre.mean_absolute_error,'Spearman'),'spearman_prediction_sd':safe(pre[v],pre.prediction_sd,'Spearman'),'association_without_top10_SSE':safe(pre.loc[~pre.top10_SSE,v],pre.loc[~pre.top10_SSE,'mean_absolute_error'],'Spearman'),'status':'exploratory; requires nested cross-fitted validation'})
 pd.DataFrame(risk).to_csv(T/'11_pre_yield_risk_signals.csv',index=False);pd.DataFrame([{'residual_definition':'y_true-y_pred','LOW_HIGH_definition':'TRAIN y quartiles Q25/Q75','difficult_definition':'existing difficult_all_3; not redefined','yatypical_definition':'existing y_outlier_given_similar_X; not redefined','large_error_thresholds':'absolute error >0.5 and >1.0 t/ha','top_SSE_definition':'top ceil(10% of squared aggregated mean residual)','representations':'frozen full-TRAIN A1/E3 coordinates; descriptive, not OOF','permutations':N_PERM,'spatial_neighbors':'symmetric 5-nearest centroid graph','circularity_warning':'error-defined groups explored on same OOF data; no predictive validation'}]).to_csv(T/'12_decision_definitions.csv',index=False)
 figures(m,g,pd.DataFrame(ov),pd.DataFrame(ge));report(m,pd.DataFrame(gy),pd.DataFrame(ge),pd.DataFrame(fa),stab,pd.DataFrame(sp),pd.DataFrame(risk),obs,(np.sum(np.array(perm)>=obs)+1)/(N_PERM+1))
def figures(m,g,ov,ge):
 plt.figure(figsize=(6,5));sns.scatterplot(m,x='y_true',y='prediction_mean',hue='yield_segment');lo=min(m.y_true.min(),m.prediction_mean.min());hi=max(m.y_true.max(),m.prediction_mean.max());plt.plot([lo,hi],[lo,hi],'k--');plt.tight_layout();plt.savefig(F/'01_observed_predicted.png',dpi=180);plt.close()
 for n,x in [(2,'y_true'),(3,'prediction_mean')]:plt.figure(figsize=(6,4));sns.scatterplot(m,x=x,y='residual_mean',hue='yield_segment');plt.axhline(0,color='black');plt.tight_layout();plt.savefig(F/f'{n:02d}_residual_vs_{x}.png',dpi=180);plt.close()
 z=m.sort_values('mean_residual_squared',ascending=False);plt.figure(figsize=(7,4));plt.plot(np.arange(1,len(z)+1)/len(z),z.mean_residual_squared.cumsum()/z.mean_residual_squared.sum());plt.xlabel('Fraction parcels');plt.ylabel('Cumulative aggregated SSE');plt.tight_layout();plt.savefig(F/'04_sse_concentration.png',dpi=180);plt.close();mats=ov.pivot(index='set_a',columns='set_b',values='jaccard');plt.figure(figsize=(7,6));sns.heatmap(mats,annot=True,fmt='.2f');plt.tight_layout();plt.savefig(F/'05_category_overlap.png',dpi=180);plt.close()
 for rid,prefix,n in [('A1','A1',6),('E3','E3',9)]:
  for color,label,off in [('y_true','yield',0),('residual_mean','residual',1),('mean_absolute_error','absolute_error',2)]:plt.figure(figsize=(6,5));sns.scatterplot(m,x=f'{prefix}_PC1',y=f'{prefix}_PC2',hue=color,palette='viridis');plt.title(f'{rid} PCA3; 2D projection');plt.tight_layout();plt.savefig(F/f'{n+off:02d}_{rid.lower()}_{label}.png',dpi=180);plt.close()
 plt.figure(figsize=(6,5));sns.scatterplot(m,x='E3_PC1',y='E3_PC2',hue='E3_prob_1',palette='coolwarm');plt.tight_layout();plt.savefig(F/'12_e3_membership.png',dpi=180);plt.close();plt.figure(figsize=(7,4));sns.boxplot(m,x='yield_segment',y='E3_prob_1');plt.tight_layout();plt.savefig(F/'13_membership_by_yield.png',dpi=180);plt.close();plt.figure(figsize=(7,4));sns.barplot(ge[ge.membership=='E3'],x='component',y='weighted_absolute_error');plt.tight_layout();plt.savefig(F/'14_error_by_component.png',dpi=180);plt.close();plt.figure(figsize=(6,4));sns.scatterplot(m,x='E3_entropy',y='mean_absolute_error',hue='top10_SSE');plt.tight_layout();plt.savefig(F/'15_error_vs_entropy.png',dpi=180);plt.close();plt.figure(figsize=(6,4));sns.scatterplot(m,x='prediction_sd',y='mean_absolute_error',hue='signed_error_pattern');plt.tight_layout();plt.savefig(F/'16_error_stability.png',dpi=180);plt.close()
 for n,col in [(17,'residual_mean'),(18,'mean_absolute_error')]:ax=g.plot(column=col,cmap='coolwarm' if n==17 else 'magma',legend=True,figsize=(7,6),edgecolor='.5',linewidth=.2);ax.set_axis_off();plt.tight_layout();plt.savefig(F/f'{n:02d}_map_{col}.png',dpi=180);plt.close()
def report(m,gy,ge,fa,stab,sp,risk,permstat,permp):
 agg_rmse=np.sqrt(m.mean_residual_squared.sum()/len(m));meanrep=np.sqrt(m.mean_squared_error.mean());slope=np.polyfit(m.y_true,m.prediction_mean,1)[0];top=m.nlargest(int(np.ceil(len(m)*.1)),'mean_residual_squared');n50=(m.sort_values('mean_residual_squared',ascending=False).mean_residual_squared.cumsum()/m.mean_residual_squared.sum()<=.5).sum()+1;gerr=ge[ge.membership=='E3'];bestassoc=fa[(fa.outcome=='mean_absolute_error')&(fa.method=='Spearman')].assign(a=lambda x:x.correlation.abs()).sort_values('a',ascending=False).head(8);ris=risk.assign(a=lambda x:x.spearman_abs_error.abs()).sort_values('a',ascending=False).head(8);txt=f'''# F3.2.1 — Structural Error & Extreme Yield Diagnostics\n\n## Controles y glosario\nSólo Champion V1 OOF congelado: 138 parcelas × 10 repeticiones, sin duplicados. Residuo `e=y−ŷ`; MAE parcela=`mean(|e_ir|)`; RMSE parcela=`sqrt(mean(e_ir²))`; SSE agregado usa `(mean_r e_ir)²`; MSE por repetición usa `mean_r(e_ir²)`. Las coordenadas A1/E3 se ajustaron previamente en TRAIN completo: asociaciones estructurales son descriptivas, no OOF.\n\n## Reconstrucción\nRMSE agregado={agg_rmse:.4f}; RMSE que conserva variación entre repeticiones={meanrep:.4f}; calibration slope={slope:.3f}. Se reproduce el benchmark 0.4903.\n\n## A. Naturaleza de los errores\n{n50} parcelas explican al menos 50% del SSE agregado; top 10%={top.mean_residual_squared.sum()/m.mean_residual_squared.sum():.1%}. Difficult={m.loc[m.difficult,'mean_residual_squared'].sum()/m.mean_residual_squared.sum():.1%}; y-atypical={m.loc[m.y_atypical,'mean_residual_squared'].sum()/m.mean_residual_squared.sum():.1%}. Tipos de estabilidad={stab.diagnostic_type.value_counts().to_dict()}. La señal dominante es sesgo recurrente/casos aislados, no variabilidad de ajuste, si `prediction_sd` permanece débilmente asociada al error.\n\n## B. Extremos\nLOW: bias e=y−ŷ={m.loc[m.yield_segment=='LOW','residual_mean'].mean():+.3f}; HIGH={m.loc[m.yield_segment=='HIGH','residual_mean'].mean():+.3f}. Signo negativo en LOW significa sobreestimación; positivo en HIGH significa subestimación: regresión hacia la media. Hay errores intermedios y los conjuntos no son equivalentes; ver solapamientos.\n\n## C. GMM\nE3 weighted errors={gerr.round(3).to_dict('records')}. Asociación membership–segmento: estadístico predefinido rango de media p1={permstat:.3f}, permutación p={permp:.4f}. Es retrospectivo y no prueba clasificación. Diferenciar perfil de rendimiento, sesgo y SSE dominado por pocos casos.\n\n## D. Factores continuos\nMayores asociaciones con MAE={bestassoc[['structural_variable','correlation','correlation_excluding_top10_SSE']].round(3).to_dict('records')}. La comparación excluyendo top-SSE revela asociaciones dominadas por casos influyentes. E3-PC3 se evaluó explícitamente, sin trato preferencial posterior.\n\n## E. Ambigüedad y estabilidad\nEntropía/probabilidad máxima están incluidas como señales estructurales, no incertidumbre calibrada. Categorías de estabilidad separan sesgo recurrente, magnitud alta e inestabilidad del ajuste. Las 10 repeticiones comparten datos de entrenamiento y no son independientes.\n\n## F. Espacio\n{sp.round(4).to_dict('records')}. Vecindad=5 centroides más cercanos, simetrizada; Moran es descriptivo y no causal.\n\n## G. Anticipabilidad\nSeñales pre-yield más asociadas={ris[['candidate_signal','spearman_abs_error','association_without_top10_SSE']].round(3).to_dict('records')}. Ninguna puede llamarse predictor de fallo sin un experimento nested cross-fitted. Difficult, y-atypical, LOW/HIGH, residuo y SSE nunca son features disponibles.\n\n## Clasificación de hipótesis\n- Regresión hacia la media: **evidencia descriptiva consistente**.\n- Pocos casos dominan SSE: **evidencia descriptiva consistente**.\n- Error explicado por memberships: **exploratorio débil**, sujeto a permutación/tamaños.\n- Error explicado por factores/distancia/entropía: **exploratorio**; si desaparece sin top-SSE, dominado por pocos casos.\n- Inestabilidad entre ajustes como causa principal: **sin evidencia** si prediction SD no se asocia.\n- Causalidad agronómica: **no evaluable**.\n\n## Decisión\nNo entrenar todavía un corrector localizado ni GMM experts. El siguiente experimento mínimo, sólo si una señal pre-yield conserva asociación al excluir top-SSE, sería un modelo de riesgo de error completamente nested y cross-fitted, evaluado por calibración de error/coverage, no por reutilizar estas etiquetas exploradas. Si no la conserva, elegir **ninguna corrección adicional**.\n\n**Respuesta final:** los errores extremos parecen dominados por regresión hacia la media y un conjunto pequeño de parcelas con sesgo recurrente. La estructura puede describir parte de su contexto, pero con estos mismos datos no demuestra que sean anticipables o corregibles reproduciblemente.\n''';(R/'f3_2_1_structural_error_diagnostics_report.md').write_text(txt,encoding='utf-8')
if __name__=='__main__':main()
